for (const l of cfg.LIGHTS) {
  const pct = cfg.INITIAL_LIGHTS_ON[l.id];
  S.lights[l.id] = { id: l.id, on: pct !== undefined, intensity: pct !== undefined ? pct : 100, color: cfg.DEFAULT_LIGHT_COLOR };
}
for (const p of cfg.PIRS) { S.pirMotion[p.id] = false; S.pirUntil[p.id] = null; S.pirAuto[p.id] = []; }
for (const dr of cfg.DOORS) S.doors[dr.id] = false;
for (const r of cfg.ROOMS) S.rooms[r.id] = { t: outdoor - cfg.CLIMATE.insulation, h: 60, lux: 0 };
for (const a of cfg.AIR_CONDITIONERS) S.acs[a.id] = { id: a.id, on: false, mode: 'cool', setpoint: 24, fan: 'mid', running: false, watts: 0 };
for (const p of cfg.PLUGS) {
  const on = !!p.initialOn;
  S.plugs[p.id] = { id: p.id, on, watts: on ? p.watts : 0, kwh: 0, offAt: on && p.autoOffSec ? Date.now() + p.autoOffSec * 1000 : null };
}

flow.set('state', S);
flow.set('seq', 1);
node.status({ fill: 'green', shape: 'dot', text: 'simulación lista · ' + d.toLocaleTimeString('es-CO') });

const evt = { id: 'nr-init-' + Date.now(), ts: Date.now(), level: 'info', source: 'Sistema', message: 'Simulación iniciada en Node-RED' };
S.events.push(evt);
const ev = { type: 'event', event: evt };
// salida 1 → telemetría · salida 2 → comando para que TODOS los clientes reciban un snapshot nuevo
return [[{ payload: ev }], [{ payload: { kind: 'snapshot.request' } }]];

// El frontend envía JSON como texto. Aquí solo se comprueba TAMAÑO y FORMA; el permiso y los valores
// los decide el nodo siguiente («Autorizar sesión y validar comando»). Todo mensaje que llega por
// el WebSocket es NO CONFIABLE hasta pasar por ese nodo.
//   - más de maxMsgBytes  → msg.parseError = 'too_large'
//   - no es JSON          → msg.parseError = 'no_json'
//   - no es objeto con kind → msg.parseError = 'schema'
// Límite honesto: el nodo «websocket» de Node-RED ya leyó el mensaje entero antes de llegar aquí; esta
// comprobación no evita que un cliente envíe un mensaje enorme (eso se limita en el proxy y con memoria del contenedor).
const sec = global.get('sec');
const MAX = (sec && sec.limits.maxMsgBytes) || 2048;
let p = msg.payload;
const bytes = Buffer.isBuffer(p) ? p.length : typeof p === 'string' ? Buffer.byteLength(p, 'utf8') : 0;
if (bytes > MAX) { msg.parseError = 'too_large'; msg.payload = {}; return msg; }
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { msg.parseError = 'no_json'; msg.payload = {}; return msg; }
}
if (!p || typeof p !== 'object' || Array.isArray(p) || typeof p.kind !== 'string') { msg.parseError = 'schema'; msg.payload = {}; return msg; }
msg.payload = p;           // msg._session se conserva: sirve para responder solo a ese cliente
return msg;

// ── Criptografía y seguridad del canal (generado) ───────────────────
const SEC = global.get('sec');
const RT = global.get('secRt');
const hmacHex = (key, data) => crypto.createHmac('sha256', key).update(data).digest('hex');
const sha256Hex = (data) => crypto.createHash('sha256').update(data).digest('hex');
const ctEq = (aHex, bHex) => { try { const a = Buffer.from(String(aHex), 'hex'), b = Buffer.from(String(bHex), 'hex'); return a.length > 0 && a.length === b.length && crypto.timingSafeEqual(a, b); } catch (e) { return false; } };
const deviceKey = (dev) => RT.devKeys[dev] || (RT.devKeys[dev] = crypto.createHmac('sha256', RT.master).update('casa-iot/device/v1/' + dev).digest());
const sortedPairs = (o) => Object.keys(o || {}).sort().map((k) => [k, o[k]]);
const canon = (m, tags, f, ts) => JSON.stringify([m, sortedPairs(tags), sortedPairs(f), ts]);
// ─────────────────────────────────────────────────────────────────────

// PUERTA ÚNICA de las órdenes que llegan por el WebSocket. Todo lo que no pase por aquí no llega al enrutador.
//   Salida 1 → enrutador (orden ya autorizada y saneada: solo las claves esperadas, con valores en rango)
//   Salida 2 → respuesta SOLO a ese cliente (msg._session): sesión, confirmación pedida o rechazo
//   Salida 3 → registros de auditoría (medición «audit» de InfluxDB)
//
// IDENTIDAD: cada sesión empieza ANÓNIMA y se empareja con la clave de un usuario (CASA_USERS: alias:rol:clave) o con una
// clave compartida (CASA_PAIRING_KEY / CASA_ADMIN_KEY, alias «compartida-…»). El alias queda en la sesión (S.user) y en
// cada registro de auditoría, así se sabe QUIÉN abrió una puerta o desarmó la alarma.
//   lector         → conexión anónima: solo ve el estado REDUCIDO (sin alarma, movimiento, puertas, eventos ni alertas).
//                    Un usuario con rol lector y clave propia ve el estado completo, pero tampoco manda órdenes.
//   operador       → luces, aires, enchufes, puertas, escenas, armar la alarma.
//   administrador  → además, simulaciones, hora simulada y revocar sesiones.
// Acciones sensibles (desarmar la alarma, abrir una puerta del perímetro, escenas que desarman) piden CONFIRMACIÓN en
// dos pasos: el servidor responde con un código de un solo uso (15 s, ligado a esta sesión) y solo ejecuta cuando
// vuelve ese código en un mensaje «confirm».
//
// La validación ocurre AQUÍ, en el servidor. Ocultar botones en la interfaz es solo comodidad, no un control.
// Límites honestos: la IP del cliente no llega a Node-RED, por eso los límites son por sesión y globales (el límite
// por IP lo da el proxy y settings.js → webSocketNodeVerifyClient); una sesión nueva se obtiene reconectando.
if (!SEC || !RT) return [null, [{ payload: { type: 'reject', kind: '?', reason: 'not_ready' }, _session: msg._session }], null];

const now = Date.now();
const L = SEC.limits;
const NAME = SEC.roles;
const key = (msg._session && msg._session.id) || 'sin-sesion';
const short = (v) => sha256Hex(String(v)).slice(0, 8);   // nunca se guarda el id de sesión completo
const toOut = [], replies = [], audits = [];
// Pide un snapshot para UNA sesión: «Filtrar por sesión y serializar» lo manda completo o reducido según su identidad
const snapshotFor = (session) => toOut.push({ payload: { kind: 'snapshot.request' }, _session: session });
const reply = (payload) => { if (msg._session) replies.push({ payload, _session: msg._session }); };
const fin = () => [toOut.length ? toOut : null, replies.length ? replies : null, audits.length ? audits : null];

// ── mantenimiento barato (cada minuto) ──
if (now - RT.lastPrune > 60000) {
  RT.lastPrune = now;
  for (const k of Object.keys(RT.sessions)) if (now - RT.sessions[k].last > (RT.sessions[k].user ? L.authedIdleMs : L.sessionIdleMs)) delete RT.sessions[k];
  for (const c of Object.keys(RT.pending)) if (RT.pending[c].exp < now) delete RT.pending[c];
  RT.helloFails = RT.helloFails.filter((t) => now - t < L.helloGlobalWindowMs);
}

let S = RT.sessions[key];
if (!S) S = RT.sessions[key] = { rank: 0, user: null, since: now, last: now, fails: 0, lockedUntil: 0, tokens: L.readBucket.cap, ts: now };
S.last = now;

const rec = (result, reason, kind, id, extra) =>
  audits.push({ payload: Object.assign({ result, reason, kind: String(kind || '?').slice(0, 40), id: id ? String(id).slice(0, 60) : '', role: NAME[S.rank], user: S.user || '', sid: short(key) }, extra || {}) });
const reject = (reason, kind, id, extra) => {
  RT.stats.rejected++;
  rec('rejected', reason, kind, id, extra);
  if (reason !== 'rate_limit') reply({ type: 'reject', kind: String(kind || '?').slice(0, 40), reason, need: extra && extra.need });   // a quien inunda no se le contesta cada mensaje
  return fin();
};

// ── 1. frecuencia por sesión (cubeta de fichas) ──
const B = S.rank > 0 ? L.controlBucket : L.readBucket;
S.tokens = Math.min(B.cap, S.tokens + ((now - S.ts) / 1000) * B.refillPerSec);
S.ts = now;
if (S.tokens < 1) return reject('rate_limit', msg.payload && msg.payload.kind);
S.tokens -= 1;

// ── 2. forma del mensaje (ya revisada en «Parsear comando») ──
if (msg.parseError) return reject(msg.parseError, '?');
const cmd = msg.payload || {};
const kind = cmd.kind;
const spec = Object.prototype.hasOwnProperty.call(SEC.kinds, kind) ? SEC.kinds[kind] : null;
if (!spec) return reject('unknown_kind', kind);
// solo las claves esperadas: así nadie puede colar campos internos (auto, quiet, reason…) ni __proto__
for (const k of Object.keys(cmd)) if (!spec.keys.includes(k)) return reject('schema', kind, cmd.id);

// ── 3. capacidades por rol ──
if (spec.role > S.rank) return reject('forbidden', kind, cmd.id, { need: NAME[spec.role] });

// ── 4. mensajes de sesión ──
if (kind === 'session.hello') {
  if (RT.frozenUntil > now) return reject('frozen', kind);
  RT.helloFails = RT.helloFails.filter((t) => now - t < L.helloGlobalWindowMs);
  if (S.lockedUntil > now || RT.helloFails.length >= L.helloGlobalMax) return reject('locked', kind);
  const k = cmd.key;
  const h = typeof k === 'string' && k.length >= 8 && k.length <= 128 ? sha256Hex(k) : null;
  let found = null;
  for (const u of RT.users) { const ok = h ? ctEq(u.hash, h) : false; if (ok && !found) found = u; }   // recorre todos: no filtra por tiempo
  if (!found) {
    S.fails++; RT.helloFails.push(now);
    if (S.fails >= L.helloFailMax) { S.lockedUntil = now + L.helloLockMs; S.fails = 0; }
    return reject('bad_key', kind);
  }
  S.rank = found.rank; S.user = found.alias; S.fails = 0; S.since = now;
  RT.stats.accepted++;
  rec('accepted', 'paired', kind);
  reply({ type: 'session', role: NAME[S.rank], user: S.user });
  snapshotFor(msg._session);   // ahora sí recibe el estado completo
  return fin();
}
if (kind === 'session.logout') {
  rec('accepted', 'logout', kind);   // antes de olvidar al usuario, para que la auditoría diga quién salió
  S.rank = 0; S.user = null;
  for (const c of Object.keys(RT.pending)) if (RT.pending[c].sid === key) delete RT.pending[c];
  RT.stats.accepted++;
  reply({ type: 'session', role: NAME[0] });
  snapshotFor(msg._session);   // vuelve al estado reducido: la pantalla deja de ver lo sensible
  return fin();
}
if (kind === 'admin.revoke') {
  let n = 0;
  for (const k of Object.keys(RT.sessions)) {
    if (k !== key && (RT.sessions[k].rank > 0 || RT.sessions[k].user)) {
      RT.sessions[k].rank = 0; RT.sessions[k].user = null; n++;
      const other = { type: 'websocket', id: k };
      replies.push({ payload: { type: 'session', role: NAME[0], revoked: true }, _session: other });
      snapshotFor(other);
    }
  }
  for (const c of Object.keys(RT.pending)) if (RT.pending[c].sid !== key) delete RT.pending[c];
  RT.frozenUntil = now + L.freezeMs;
  RT.stats.accepted++;
  rec('accepted', 'revoked', kind, '', { count: n });
  reply({ type: 'session', role: NAME[S.rank], user: S.user, note: 'revocadas ' + n });
  toOut.push({ payload: { kind: 'security.notice', level: 'warning', message: 'Sesiones de control revocadas (' + n + ') · emparejamiento congelado ' + Math.round(L.freezeMs / 60000) + ' min' } });
  return fin();
}
if (kind === 'confirm') {
  const code = typeof cmd.code === 'string' && /^[0-9a-f]{8}$/.test(cmd.code) ? cmd.code : null;
  const p = code ? RT.pending[code] : null;
  if (!p) return reject('bad_confirm', kind);                       // inexistente, ya usado (repetición) o mal escrito
  if (p.sid !== key) return reject('bad_confirm', kind, p.cmd.id);  // el código es de otra sesión
  delete RT.pending[code];                                          // un solo uso, también si caducó
  if (p.exp < now) return reject('expired', kind, p.cmd.id);
  if (S.rank < p.need) return reject('forbidden', kind, p.cmd.id, { need: NAME[p.need] });
  RT.stats.accepted++;
  rec('accepted', 'confirmed', p.cmd.kind, p.cmd.id, { confirmed: true });
  toOut.push({ payload: p.cmd, _session: msg._session });
  return fin();
}

// ── 5. órdenes de dispositivos: esquema estricto y rangos ──
const isObj = (o) => !!o && typeof o === 'object' && !Array.isArray(o);
const isNum = (v, a, b) => typeof v === 'number' && Number.isFinite(v) && v >= a && v <= b;
const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
const known = (list, v) => typeof v === 'string' && list.includes(v);
const cfg = global.get('cfg') || {};   // nombres legibles de puertas y escenas para el texto del cuadro de confirmación
const label = (list, id) => { const x = (list || []).find((i) => i.id === id); return x ? x.label : id; };
let clean = null, sensitive = null;

switch (kind) {
  case 'snapshot.request':
    clean = { kind };
    break;
  case 'light.set': {
    if (!known(SEC.ids.light, cmd.id)) return reject('unknown_id', kind, cmd.id);
    if (!isObj(cmd.patch)) return reject('schema', kind, cmd.id);
    const ks = Object.keys(cmd.patch);
    if (!ks.length || ks.some((k) => !['on', 'intensity', 'color'].includes(k))) return reject('schema', kind, cmd.id);
    const patch = {};
    if (has(cmd.patch, 'on')) { if (typeof cmd.patch.on !== 'boolean') return reject('schema', kind, cmd.id); patch.on = cmd.patch.on; }
    if (has(cmd.patch, 'intensity')) { if (!isNum(cmd.patch.intensity, SEC.ranges.intensity[0], SEC.ranges.intensity[1])) return reject('range', kind, cmd.id); patch.intensity = cmd.patch.intensity; }
    if (has(cmd.patch, 'color')) { if (typeof cmd.patch.color !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(cmd.patch.color)) return reject('range', kind, cmd.id); patch.color = cmd.patch.color; }
    clean = { kind, id: cmd.id, patch };
    break;
  }
  case 'ac.set': {
    if (!known(SEC.ids.ac, cmd.id)) return reject('unknown_id', kind, cmd.id);
    if (!isObj(cmd.patch)) return reject('schema', kind, cmd.id);
    const ks = Object.keys(cmd.patch);
    if (!ks.length || ks.some((k) => !['on', 'mode', 'setpoint', 'fan'].includes(k))) return reject('schema', kind, cmd.id);
    const patch = {};
    if (has(cmd.patch, 'on')) { if (typeof cmd.patch.on !== 'boolean') return reject('schema', kind, cmd.id); patch.on = cmd.patch.on; }
    if (has(cmd.patch, 'mode')) { if (cmd.patch.mode !== 'cool' && cmd.patch.mode !== 'fan') return reject('range', kind, cmd.id); patch.mode = cmd.patch.mode; }
    if (has(cmd.patch, 'fan')) { if (!['low', 'mid', 'high'].includes(cmd.patch.fan)) return reject('range', kind, cmd.id); patch.fan = cmd.patch.fan; }
    if (has(cmd.patch, 'setpoint')) { if (!isNum(cmd.patch.setpoint, SEC.ranges.setpoint[0], SEC.ranges.setpoint[1])) return reject('range', kind, cmd.id); patch.setpoint = cmd.patch.setpoint; }
    clean = { kind, id: cmd.id, patch };
    break;
  }
  case 'plug.set':
    if (!known(SEC.ids.plug, cmd.id)) return reject('unknown_id', kind, cmd.id);
    if (typeof cmd.on !== 'boolean') return reject('schema', kind, cmd.id);
    clean = { kind, id: cmd.id, on: cmd.on };
    break;
  case 'door.set':
    if (!known(SEC.ids.door, cmd.id)) return reject('unknown_id', kind, cmd.id);
    if (typeof cmd.open !== 'boolean') return reject('schema', kind, cmd.id);
    clean = { kind, id: cmd.id, open: cmd.open };
    if (cmd.open && SEC.ids.doorExterior.includes(cmd.id)) sensitive = 'Abrir «' + label(cfg.DOORS, cmd.id) + '» (puerta del perímetro)';
    break;
  case 'scene.apply':
    if (!known(SEC.ids.scene, cmd.id)) return reject('unknown_id', kind, cmd.id);
    clean = { kind, id: cmd.id };
    if (SEC.ids.sceneDisarms.includes(cmd.id)) sensitive = 'Aplicar la escena «' + label(cfg.SCENES, cmd.id) + '» (desarma la alarma)';
    break;
  case 'security.set':
    if (!['disarmed', 'home', 'away'].includes(cmd.mode)) return reject('range', kind);
    clean = { kind, mode: cmd.mode };
    if (cmd.mode === 'disarmed') sensitive = 'Desarmar la alarma';
    break;
  case 'security.simulateIntrusion':
    clean = { kind };
    break;
  case 'smoke.simulate':
  case 'heat.simulate':
  case 'humidity.simulate':
    if (typeof cmd.active !== 'boolean') return reject('schema', kind);
    clean = { kind, active: cmd.active };
    break;
  case 'pir.simulate':
    if (!known(SEC.ids.pir, cmd.id)) return reject('unknown_id', kind, cmd.id);
    clean = { kind, id: cmd.id };
    break;
  case 'world.setHour':
    if (cmd.hour !== null && !isNum(cmd.hour, SEC.ranges.hour[0], SEC.ranges.hour[1])) return reject('range', kind);
    clean = { kind, hour: cmd.hour };
    break;
  default:
    return reject('unknown_kind', kind);
}

// ── 6. acciones sensibles: confirmación en dos pasos ──
if (sensitive) {
  const mine = Object.keys(RT.pending).filter((c) => RT.pending[c].sid === key);
  while (mine.length >= L.maxPendingPerSession) delete RT.pending[mine.shift()];
  const code = crypto.randomBytes(4).toString('hex');
  RT.pending[code] = { sid: key, cmd: clean, need: spec.role, exp: now + L.confirmTtlMs, summary: sensitive };
  rec('pending', 'confirm_required', kind, clean.id);
  reply({ type: 'confirm', code, kind, summary: sensitive, ttlMs: L.confirmTtlMs });
  return fin();
}

RT.stats.accepted++;
rec('accepted', 'ok', kind, clean.id);
toOut.push({ payload: clean, _session: msg._session });
return fin();

// ── Criptografía y seguridad del canal (generado) ───────────────────
const SEC = global.get('sec');
const RT = global.get('secRt');
const hmacHex = (key, data) => crypto.createHmac('sha256', key).update(data).digest('hex');
const sha256Hex = (data) => crypto.createHash('sha256').update(data).digest('hex');
const ctEq = (aHex, bHex) => { try { const a = Buffer.from(String(aHex), 'hex'), b = Buffer.from(String(bHex), 'hex'); return a.length > 0 && a.length === b.length && crypto.timingSafeEqual(a, b); } catch (e) { return false; } };
const deviceKey = (dev) => RT.devKeys[dev] || (RT.devKeys[dev] = crypto.createHmac('sha256', RT.master).update('casa-iot/device/v1/' + dev).digest());
const sortedPairs = (o) => Object.keys(o || {}).sort().map((k) => [k, o[k]]);
const canon = (m, tags, f, ts) => JSON.stringify([m, sortedPairs(tags), sortedPairs(f), ts]);
// ─────────────────────────────────────────────────────────────────────

// Recibe registros {result, reason, kind, id, role, user, sid, …} de «Autorizar sesión» y de «Validar telemetría».
//   Salida 1 → puntos de InfluxDB:  audit (tags result, reason, kind, role → id, user, session, confirmed, count)
//                                  user = alias del usuario que emparejó la sesión (CASA_USERS o «compartida-…»); vacío si era anónima
//                                  quarantine (tags dev, measurement, reason → summary): lecturas descartadas por anomalía
//   Salida 2 → órdenes internas «security.notice»: un aviso en el registro de eventos por motivo, como máximo cada noticeEveryMs
// Sin secretos: la sesión se guarda como un resumen de 8 caracteres y nunca se guardan claves, firmas ni mensajes completos.
// Una inundación no puede llenar InfluxDB: hay un tope de puntos por segundo; lo que sobra se cuenta y se resume en un solo punto.
const r = msg.payload || {};
const now = Date.now();
const L = SEC.limits;
const A = RT.audit;

// cubeta de fichas para InfluxDB
A.tokens = Math.min(L.auditBucket.cap, A.tokens + ((now - A.ts) / 1000) * L.auditBucket.refillPerSec);
A.ts = now;
const points = [];
if (A.tokens >= 1) {
  A.tokens -= 1;
  const tags = { result: String(r.result || '?'), reason: String(r.reason || '?'), kind: String(r.kind || '?'), role: String(r.role || '?') };
  const fields = { id: String(r.id || ''), session: String(r.sid || ''), count: typeof r.count === 'number' ? r.count : 1 };
  if (r.user) fields.user = String(r.user).slice(0, 32);
  if (r.confirmed) fields.confirmed = true;
  points.push({ measurement: 'audit', tags, fields, timestamp: new Date(now) });
  if (r.quarantine) {
    const q = r.quarantine;
    points.push({ measurement: 'quarantine', tags: { dev: String(q.dev || '?').slice(0, 60), measurement: String(q.m || '?').slice(0, 30), reason: tags.reason }, fields: { summary: String(q.summary || '').slice(0, 300) }, timestamp: new Date(now) });
  }
} else {
  A.dropped++;
}
if (A.dropped > 0 && now - A.lastDropAt > 1000 && A.tokens >= 1) {
  A.tokens -= 1;
  points.push({ measurement: 'audit', tags: { result: 'rejected', reason: 'flood', kind: 'audit.drop', role: '-' }, fields: { id: '', session: '', count: A.dropped }, timestamp: new Date(now) });
  A.dropped = 0; A.lastDropAt = now;
}

// aviso legible en el registro de eventos (solo rechazos; uno por motivo cada noticeEveryMs)
const WHY = {
  bad_key: 'clave de emparejamiento incorrecta', locked: 'emparejamiento bloqueado por intentos fallidos', frozen: 'emparejamiento congelado por un administrador',
  forbidden: 'orden sin permiso para el rol de la sesión', unknown_kind: 'tipo de orden desconocido', unknown_id: 'dispositivo inexistente', schema: 'mensaje con forma inválida',
  range: 'valor fuera de rango', too_large: 'mensaje demasiado grande', no_json: 'mensaje que no es JSON', rate_limit: 'demasiados mensajes por segundo',
  bad_confirm: 'código de confirmación inválido o repetido', expired: 'código de confirmación caducado',
  bad_signature: 'firma HMAC inválida', replay: 'mensaje repetido (número de secuencia ya usado)', stale: 'mensaje fuera de la ventana de tiempo', unknown_device: 'dispositivo no registrado',
  anomaly: 'lectura físicamente imposible (en cuarentena)', envelope: 'sobre de telemetría mal formado', disabled: 'ingesta deshabilitada',
};
const cmds = [];
if (r.result === 'rejected' && r.reason !== 'flood') {
  const a = RT.notice[r.reason] || (RT.notice[r.reason] = { last: 0, n: 0 });
  if (now - a.last >= L.noticeEveryMs) {
    const more = a.n > 0 ? ' (+' + a.n + ' más)' : '';
    const quien = r.dev ? ' · ' + r.dev : r.kind && r.kind !== '?' ? ' · ' + r.kind : '';
    cmds.push({ payload: { kind: 'security.notice', level: r.reason === 'bad_signature' || r.reason === 'replay' || r.reason === 'anomaly' ? 'critical' : 'warning', message: 'Rechazado: ' + (WHY[r.reason] || r.reason) + quien + more } });
    a.last = now; a.n = 0;
  } else {
    a.n++;
  }
}
return [points.length ? { payload: points } : null, cmds.length ? cmds : null];

// ── Criptografía y seguridad del canal (generado) ───────────────────
const SEC = global.get('sec');
const RT = global.get('secRt');
const hmacHex = (key, data) => crypto.createHmac('sha256', key).update(data).digest('hex');
const sha256Hex = (data) => crypto.createHash('sha256').update(data).digest('hex');
