const nameOf = (list, id) => { const x = list.find((i) => i.id === id); return x ? x.label : id; };
function log(level, source, message, quiet) {
  if (quiet && level === 'info') return;
  const ev = { id: 'nr-' + now + '-' + (seq++), ts: now, level, source, message };
  out.push({ type: 'event', event: ev });
  const ring = S.events || (S.events = []);      // últimos 50: se envían a quien abra la página después
  ring.push(ev);
  if (ring.length > 50) ring.shift();
}
const wrap = (arr) => arr.map((p) => ({ payload: p }));
function done() {
  flow.set('seq', seq);
  flow.set('state', S);
  return [wrap(out), [msg]];
}
// ── Fin del preámbulo ────────────────────────────────────────────────
// Compara las lecturas con los umbrales de cfg.ALERTS y levanta o normaliza alertas (con histéresis para que no parpadeen).
// Cada cambio sale como mensaje `alert`: la interfaz lo muestra y se guarda en InfluxDB (measurement «alerts»).
const A = cfg.ALERTS;
const want = {};
if (S.smoke.alarm) want.humo = { level: 'critical', message: 'Humo ' + Math.round(S.smoke.ppm) + ' ppm en la cocina (umbral ' + cfg.SMOKE.alarmThresholdPpm + ')' };
if (S.security.alarm) want.intrusion = { level: 'critical', message: S.security.cause || 'Intrusión detectada' };
for (const r of cfg.ROOMS) {
  const st = S.rooms[r.id];
  const tid = 'temperatura:' + r.id;
  if (st.t > A.tempHighC || (S.alerts[tid] && st.t > A.tempHighClearC)) want[tid] = { level: 'warning', message: 'Temperatura alta en ' + r.label + ': ' + st.t.toFixed(1) + ' °C' };
  const hid = 'humedad:' + r.id;
  if (st.h > A.humidityHighPct || (S.alerts[hid] && st.h > A.humidityHighClearPct)) want[hid] = { level: 'warning', message: 'Humedad alta en ' + r.label + ': ' + Math.round(st.h) + ' %' };
}
const w = S.lastPower ? S.lastPower.watts : 0;
if (w > A.powerHighW || (S.alerts.consumo && w > A.powerHighClearW)) want.consumo = { level: 'warning', message: 'Consumo alto: ' + Math.round(w) + ' W' };

const quiet = (id) => id === 'humo' || id === 'intrusion';   // estas dos ya registran su propio evento
for (const id of Object.keys(want)) {
  if (S.alerts[id]) continue;
  S.alerts[id] = { level: want[id].level, message: want[id].message, since: now };
  out.push({ type: 'alert', ts: now, id, active: true, level: want[id].level, message: want[id].message });
  if (!quiet(id)) log('warning', 'Alerta', want[id].message);
}
for (const id of Object.keys(S.alerts)) {
  if (want[id]) continue;
  const lvl = S.alerts[id].level;
  delete S.alerts[id];
  out.push({ type: 'alert', ts: now, id, active: false, level: lvl, message: '' });
  if (!quiet(id)) log('info', 'Alerta', 'Normalizada: ' + id.replace(':', ' · '));
}
return done();

// Cada cfg.INFLUX.persistEverySec segundos arma UN lote con todas las mediciones periódicas.
// Esquema (measurement · tags → fields):
//   power  · meter        → watts, kwh, base, lights, ac, plugs
//   smoke  · sensor       → ppm, alarm, simulating
//   env    · room, sensor → temperature, humidity, lux   (sensor = "DHT22-<habitación>"; room "exterior" = temperatura exterior)
//   ac     · id, room     → on, mode, setpoint, running, watts
//   plug   · id, room     → on, watts, kwh
const cfg = global.get('cfg');
const S = flow.get('state');
if (!cfg || !S) return null;

const every = (cfg.INFLUX && cfg.INFLUX.persistEverySec) || 2;
const n = (context.get('n') || 0) + 1;
context.set('n', n);
if (n % every !== 0) return null;

const round = (v, d) => Math.round(v * Math.pow(10, d)) / Math.pow(10, d);
const ts = new Date();
const pts = [];

const P = S.lastPower;
if (P) {
  pts.push({ measurement: 'power', tags: { meter: 'Medidor_General' }, timestamp: ts,
    fields: { watts: P.watts, kwh: round(P.kwhTotal, 6), base: P.breakdown.base, lights: P.breakdown.lights, ac: P.breakdown.ac, plugs: P.breakdown.plugs } });
}
pts.push({ measurement: 'smoke', tags: { sensor: cfg.SMOKE.id }, timestamp: ts,
  fields: { ppm: Math.round(S.smoke.ppm), alarm: S.smoke.alarm, simulating: S.smoke.leak } });

for (const r of cfg.ROOMS) {
  const st = S.rooms[r.id];
  pts.push({ measurement: 'env', tags: { room: r.id, sensor: 'DHT22-' + r.id }, timestamp: ts,
    fields: { temperature: round(st.t, 2), humidity: round(st.h, 1), lux: Math.round(st.lux || 0) } });
}
const o = cfg.CLIMATE.outdoor;
const hour = S.hourOverride !== null ? S.hourOverride : new Date().getHours() + new Date().getMinutes() / 60;
pts.push({ measurement: 'env', tags: { room: 'exterior', sensor: 'exterior' }, timestamp: ts,
  fields: { temperature: round(o.mean + o.amp * Math.cos(((hour - o.peakHour) / 24) * 2 * Math.PI), 2) } });

for (const a of cfg.AIR_CONDITIONERS) {
  const s = S.acs[a.id];
  pts.push({ measurement: 'ac', tags: { id: a.id, room: a.room }, timestamp: ts,
    fields: { on: s.on, mode: s.mode, setpoint: s.setpoint, running: s.running, watts: s.watts } });
}
for (const p of cfg.PLUGS) {
  const s = S.plugs[p.id];
  pts.push({ measurement: 'plug', tags: { id: p.id, room: p.room }, timestamp: ts,
    fields: { on: s.on, watts: s.watts, kwh: round(s.kwh, 6) } });
}

msg.payload = pts;
// Contadores para el panel «Pipeline IoT» de la interfaz (lo que Node-RED envía a InfluxDB)
const pp = S.pipe;
pp.batches += 1; pp.points += pts.length; pp.lastBatchAt = Date.now();
const tel = { payload: { type: 'pipeline', ts: pp.lastBatchAt, writes: { batches: pp.batches, points: pp.points, lastBatchAt: pp.lastBatchAt, errors: pp.errors, lastError: pp.lastError, lastErrorAt: pp.lastErrorAt } } };
node.status({ fill: 'blue', shape: 'dot', text: pts.length + ' puntos · ' + ts.toLocaleTimeString('es-CO') });
return [msg, tel];

// ── Criptografía y seguridad del canal (generado) ───────────────────
const SEC = global.get('sec');
const RT = global.get('secRt');
const hmacHex = (key, data) => crypto.createHmac('sha256', key).update(data).digest('hex');
const sha256Hex = (data) => crypto.createHash('sha256').update(data).digest('hex');
const ctEq = (aHex, bHex) => { try { const a = Buffer.from(String(aHex), 'hex'), b = Buffer.from(String(bHex), 'hex'); return a.length > 0 && a.length === b.length && crypto.timingSafeEqual(a, b); } catch (e) { return false; } };
const deviceKey = (dev) => RT.devKeys[dev] || (RT.devKeys[dev] = crypto.createHmac('sha256', RT.master).update('casa-iot/device/v1/' + dev).digest());
const sortedPairs = (o) => Object.keys(o || {}).sort().map((k) => [k, o[k]]);
const canon = (m, tags, f, ts) => JSON.stringify([m, sortedPairs(tags), sortedPairs(f), ts]);
