// PRIVACIDAD antes del WebSocket. Lo que dice si la casa está vacía (modo de la alarma, movimiento, puertas, eventos, alertas,
// luces y consumo) solo llega a sesiones EMPAREJADAS con una clave (S.user, cualquier rol).
// Una conexión anónima recibe el snapshot REDUCIDO (sin SEC.privacy.hiddenState, con restricted: true), nunca los
// mensajes SEC.privacy.hiddenTypes y el clima sin SEC.privacy.hiddenClimateFields (la luminosidad delata las luces).
// Si la política no está lista, no sale nada (falla cerrado).
// msg._session (si existe) hace que el WebSocket responda solo a ese cliente; sin él, el mensaje va a todos.
const PV = SEC && SEC.privacy;
if (!PV || !RT) return null;
const P = msg.payload || {};
const hidden = PV.hiddenTypes.includes(P.type);
const full = (sid) => { const s = RT.sessions[sid]; return !!(s && s.user); };
const cleanRooms = (rooms) => {
  const out = {};
  for (const [id, r] of Object.entries(rooms || {})) {
    const c = Object.assign({}, r);
    for (const f of PV.hiddenClimateFields) delete c[f];
    out[id] = c;
  }
  return out;
};
// Versión para una pantalla anónima: null = no se le manda
const reduce = (p) => {
  if (p.type === 'snapshot') {
    const st = Object.assign({}, p.state);
    for (const k of PV.hiddenState) delete st[k];
    if (st.climate) st.climate = cleanRooms(st.climate);
    st.restricted = true;
    return { type: 'snapshot', state: st };
  }
  if (p.type === 'climate') return Object.assign({}, p, { rooms: cleanRooms(p.rooms) });
  return PV.hiddenTypes.includes(p.type) ? null : p;
};
// Solo cambian para una anónima: el snapshot, el clima y lo oculto
const differs = P.type === 'snapshot' || P.type === 'climate' || hidden;
const to = (sid, text) => ({ payload: text, _session: { type: 'websocket', id: sid } });

if (msg._session) {
  const p = full(msg._session.id) ? P : reduce(P);
  return p ? { payload: JSON.stringify(p), _session: msg._session } : null;
}
if (!differs) return { payload: JSON.stringify(P) };
const fullText = JSON.stringify(P);
const paired = Object.keys(RT.sessions).filter(full);
// Clima: la versión SIN luminosidad va a todos (también a una pantalla que aún no mandó nada y por eso no está en
// RT.sessions); justo después las emparejadas reciben la completa, que es la que les queda.
if (P.type === 'climate') return [[{ payload: JSON.stringify(reduce(P)) }, ...paired.map((sid) => to(sid, fullText))]];
// Lo oculto, solo a las emparejadas
if (hidden) return [paired.map((sid) => to(sid, fullText))];
// Snapshot del sistema (reinicio): cada sesión en su versión
const reducedText = JSON.stringify(reduce(P));
return [Object.keys(RT.sessions).map((sid) => to(sid, full(sid) ? fullText : reducedText))];

// Los cambios (luz, puerta, PIR, seguridad) y el log de eventos se guardan en el momento en que ocurren.
//   light · id → on, intensity, color      door · id → open      pir · id → motion
//   security   → mode, alarm, cause        events · level, source → message, id
const S = flow.get('state');
const m = msg.payload;
if (!m || !S) return null;
const ts = new Date(m.ts || (m.event && m.event.ts) || Date.now());
let pt = null;

switch (m.type) {
  case 'event':
    pt = { measurement: 'events', tags: { level: m.event.level, source: m.event.source }, timestamp: ts,
      fields: { message: String(m.event.message), id: String(m.event.id) } };
    break;
  case 'light': {
    const l = S.lights[m.id];
    if (l) pt = { measurement: 'light', tags: { id: m.id }, timestamp: ts, fields: { on: l.on, intensity: l.intensity, color: l.color } };
    break;
  }
  case 'door':
    pt = { measurement: 'door', tags: { id: m.id }, timestamp: ts, fields: { open: m.open } };
    break;
  case 'pir':
    pt = { measurement: 'pir', tags: { id: m.id }, timestamp: ts, fields: { motion: m.motion } };
    break;
  case 'alert':
    pt = { measurement: 'alerts', tags: { id: m.id, level: m.level }, timestamp: ts, fields: { active: !!m.active, message: String(m.message || '') } };
    break;
  case 'security':
    pt = { measurement: 'security', tags: {}, timestamp: ts, fields: { mode: m.state.mode, alarm: m.state.alarm, cause: m.state.cause || '' } };
    break;
}
if (!pt) return null;
msg.payload = [pt];
return msg;

// ── Criptografía y seguridad del canal (generado) ───────────────────
const SEC = global.get('sec');
const RT = global.get('secRt');
const hmacHex = (key, data) => crypto.createHmac('sha256', key).update(data).digest('hex');
const sha256Hex = (data) => crypto.createHash('sha256').update(data).digest('hex');
const ctEq = (aHex, bHex) => { try { const a = Buffer.from(String(aHex), 'hex'), b = Buffer.from(String(bHex), 'hex'); return a.length > 0 && a.length === b.length && crypto.timingSafeEqual(a, b); } catch (e) { return false; } };
const deviceKey = (dev) => RT.devKeys[dev] || (RT.devKeys[dev] = crypto.createHmac('sha256', RT.master).update('casa-iot/device/v1/' + dev).digest());
const sortedPairs = (o) => Object.keys(o || {}).sort().map((k) => [k, o[k]]);
const canon = (m, tags, f, ts) => JSON.stringify([m, sortedPairs(tags), sortedPairs(f), ts]);
// ─────────────────────────────────────────────────────────────────────

// INTEGRIDAD DEL DATO. Cada punto que Node-RED va a guardar sale como un MENSAJE FIRMADO de su dispositivo simulado:
//   { dev, body, sig }
//     dev  identidad del dispositivo, p. ej. «sensor:DHT22-sala» o «ac:AC_Sala_Principal»
//     body texto JSON {"v":1,"dev","m" medición,"tags","f" campos,"ts" ms,"seq" contador del dispositivo}
//     sig  HMAC-SHA256(clave del dispositivo, body)  ← la clave se deriva de CASA_DEVICE_KEY: HMAC(maestra, «casa-iot/device/v1/»+dev)
// El nodo siguiente («Validar telemetría») verifica todo ANTES de escribir en InfluxDB.
// Límite honesto: aquí el dispositivo y el validador viven en el mismo Node-RED, así que esto NO protege contra
// alguien que ya controle Node-RED. Protege el camino entre la generación y la base de datos, deja el contrato listo
// para un dispositivo real (ESP32 firmando por su cuenta, ver POST /api/ingest) y permite detectar alteraciones del histórico.
const pts = Array.isArray(msg.payload) ? msg.payload : [];
const devOf = (pt) => {
  const t = pt.tags || {};
  switch (pt.measurement) {
    case 'power': return 'meter:' + t.meter;
    case 'smoke': case 'env': return 'sensor:' + t.sensor;
    case 'ac': case 'plug': case 'light': case 'door': case 'pir': return pt.measurement + ':' + t.id;
    case 'security': return 'core:security';
    case 'alerts': return 'core:alerts';
    case 'events': return 'core:events';
    default: return 'desconocido:' + pt.measurement;
  }
};
const envs = [];
for (const pt of pts) {
  const dev = devOf(pt);
  const seq = (RT.seqOut[dev] = (RT.seqOut[dev] || 0) + 1);
  const ts = pt.timestamp instanceof Date ? pt.timestamp.getTime() : Date.now();
  const body = JSON.stringify({ v: 1, dev, m: pt.measurement, tags: pt.tags || {}, f: pt.fields, ts, seq });
  envs.push({ dev, body, sig: hmacHex(deviceKey(dev), body) });
}
return { payload: envs };

// ── Criptografía y seguridad del canal (generado) ───────────────────
const SEC = global.get('sec');
const RT = global.get('secRt');
const hmacHex = (key, data) => crypto.createHmac('sha256', key).update(data).digest('hex');
const sha256Hex = (data) => crypto.createHash('sha256').update(data).digest('hex');
const ctEq = (aHex, bHex) => { try { const a = Buffer.from(String(aHex), 'hex'), b = Buffer.from(String(bHex), 'hex'); return a.length > 0 && a.length === b.length && crypto.timingSafeEqual(a, b); } catch (e) { return false; } };
const deviceKey = (dev) => RT.devKeys[dev] || (RT.devKeys[dev] = crypto.createHmac('sha256', RT.master).update('casa-iot/device/v1/' + dev).digest());
const sortedPairs = (o) => Object.keys(o || {}).sort().map((k) => [k, o[k]]);
const canon = (m, tags, f, ts) => JSON.stringify([m, sortedPairs(tags), sortedPairs(f), ts]);
// ─────────────────────────────────────────────────────────────────────

// ── Cabeceras de la API: CORS restringido al origen del frontend (generado) ─
function apiHeaders(req) {
  const h = { 'content-type': 'application/json', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' };
  const origin = req && req.headers && req.headers.origin;
  const allowed = String(env.get('CASA_ALLOWED_ORIGINS') || 'http://localhost:5173,http://127.0.0.1:5173,http://localhost:4173,http://127.0.0.1:4173').split(',').map((x) => x.trim()).filter(Boolean);
  if (origin && allowed.includes(origin)) { h['Access-Control-Allow-Origin'] = origin; h['Vary'] = 'Origin'; }   // sin origen permitido no se envía la cabecera: el navegador bloquea la respuesta
  return h;
}
// ─────────────────────────────────────────────────────────────────────

// ÚNICO camino hacia InfluxDB para la telemetría. Cada mensaje {dev, body, sig} pasa estas comprobaciones, en este orden:
//   envelope        el sobre tiene la forma esperada
//   unknown_device  el dispositivo existe en la configuración de la casa (y, si viene de /api/ingest, acepta ingesta)
//   bad_signature   HMAC-SHA256 correcto con la clave de ESE dispositivo (comparación en tiempo constante)
//   stale           la marca de tiempo está dentro de la ventana (telemetry.windowMs)
//   replay          el número de secuencia es MAYOR que el último aceptado de ese dispositivo. Para los dispositivos
//                   externos (/api/ingest) el último número se guarda EN DISCO (contexto «persistente», ver settings.js)
//                   y, tras un reinicio, además se rechaza lo firmado ANTES de que arrancara Node-RED: así reiniciar no
//                   abre una ventana para reenviar mensajes capturados. Un dispositivo real debe usar un seq que no
//                   vuelva a empezar al reiniciarse él (p. ej. milisegundos de su reloj).
//   schema / range  medición, etiquetas y campos permitidos, con tipo y rango válidos; todo lo demás se descarta
//   anomaly         salto físicamente imposible respecto de la lectura anterior → CUARENTENA (no entra como dato confiable)
// Además agrupa los puntos aceptados en bloques de tiempo y, al cerrar cada bloque, escribe su HUELLA:
//   hash = HMAC(clave de integridad, prev : bloque : cantidad : SHA256(hashes de los puntos ordenados))
// Cada huella incluye la anterior (cadena): borrar o alterar puntos o bloques después se puede detectar con infra/verificar-integridad.mjs.
// Límites: la huella dice QUE un bloque cambió, no CUÁL punto; la cadena vuelve a empezar (GENESIS) cuando se reinicia Node-RED;
// y quien tenga la clave CASA_DEVICE_KEY podría fabricar huellas válidas (firmante y validador son el mismo Node-RED).
//   Salida 1 → puntos aceptados → InfluxDB   Salida 2 → auditoría   Salida 3 → respuesta HTTP (solo ingesta)   Salida 4 → huellas → InfluxDB
const T = SEC.telemetry;
const now = Date.now();
const envs = Array.isArray(msg.payload) ? msg.payload : [];
const reg = RT.reg || (RT.reg = Object.fromEntries(T.devices.map((d) => [d.dev, d])));
const good = [], audits = [], results = [];
const ingest = !!msg._ingest;
// Últimos números de secuencia de los dispositivos externos, en disco (sobreviven a un reinicio). Solo se lee si hace falta.
const seen = ingest ? (global.get('antiReplay', 'persistente') || {}) : null;
let seenDirty = false;
const SAFE = /^[^\u0000-\u001f]{1,80}$/;
const HEX = /^#[0-9a-fA-F]{6}$/;

const ruleCheck = (rule, v) => {
  switch (rule.t) {
    case 'num': return typeof v !== 'number' || !Number.isFinite(v) ? 'schema' : v < rule.min || v > rule.max ? 'range' : null;
    case 'bool': return typeof v === 'boolean' ? null : 'schema';
    case 'str': return typeof v !== 'string' ? 'schema' : v.length > rule.max ? 'range' : null;
    case 'enum': return typeof v !== 'string' ? 'schema' : rule.v.includes(v) ? null : 'range';
    case 'hex': return typeof v === 'string' && HEX.test(v) ? null : 'range';
  }
  return 'schema';
};

envs.forEach((e, i) => {
  let dev = e && typeof e.dev === 'string' ? e.dev.slice(0, 60) : '?';
  const fail = (reason, extra) => {
    RT.stats.telemetryRejected++;
    audits.push({ payload: Object.assign({ result: 'rejected', reason, kind: 'telemetry', id: dev, role: 'dispositivo', sid: '', dev }, extra || {}) });
    results.push({ i, ok: false, reason });
  };
  if (!e || typeof e.dev !== 'string' || typeof e.body !== 'string' || typeof e.sig !== 'string' || e.body.length > 4096 || !/^[0-9a-f]{64}$/.test(e.sig)) return fail('envelope');
  const d = reg[e.dev];
  if (!d || (ingest && !d.ingest)) return fail('unknown_device');
  if (!ctEq(hmacHex(deviceKey(e.dev), e.body), e.sig)) return fail('bad_signature');   // desde aquí el mensaje es AUTÉNTICO

  let b;
  try { b = JSON.parse(e.body); } catch (x) { return fail('envelope'); }
  if (!b || b.v !== 1 || b.dev !== e.dev || typeof b.m !== 'string' || !b.tags || typeof b.tags !== 'object' || Array.isArray(b.tags) || !b.f || typeof b.f !== 'object' || Array.isArray(b.f) || !Number.isInteger(b.ts) || !Number.isInteger(b.seq) || b.seq < 0) return fail('envelope');
  if (Math.abs(now - b.ts) > T.windowMs) return fail('stale');
  if (ingest && b.ts < RT.startedAt) return fail('stale');   // firmado antes de este arranque: pudo aceptarse antes del reinicio
  const last = Math.max(RT.lastSeq[e.dev] || 0, (ingest && seen[e.dev]) || 0);
  if (b.seq <= last) return fail('replay');
  RT.lastSeq[e.dev] = b.seq;
  if (ingest) { seen[e.dev] = b.seq; seenDirty = true; }

  const sch = T.schema[b.m];
  if (!sch || b.m !== d.m) return fail('schema');
  const tk = Object.keys(b.tags);
  if (d.tags) {                                   // dispositivo con etiquetas fijas: deben coincidir exactamente
    const dk = Object.keys(d.tags);
    if (tk.length !== dk.length || dk.some((k) => b.tags[k] !== d.tags[k])) return fail('schema');
  } else {                                        // eventos y alertas del propio sistema: mismas claves, texto seguro
    if (tk.length !== sch.tags.length || sch.tags.some((k) => typeof b.tags[k] !== 'string' || !SAFE.test(b.tags[k]))) return fail('schema');
    if (b.tags.level !== undefined && !['info', 'warning', 'critical'].includes(b.tags.level)) return fail('range');
  }
  const fk = Object.keys(b.f);
  if (!fk.length || fk.some((k) => !Object.prototype.hasOwnProperty.call(sch.fields, k))) return fail('schema');
  for (const k of fk) { const why = ruleCheck(sch.fields[k], b.f[k]); if (why) return fail(why); }

  // anomalías: saltos que la física no permite entre dos lecturas cercanas del mismo sensor
  for (const k of fk) {
    const lim = T.maxJump[k];
    if (!lim) continue;
    const prev = RT.lastVal[e.dev + '|' + k];
    if (prev && Math.abs(b.ts - prev.ts) <= T.jumpMaxGapMs && Math.abs(b.f[k] - prev.v) > lim) {
      return fail('anomaly', { quarantine: { dev: e.dev, m: b.m, summary: k + ': ' + prev.v + ' → ' + b.f[k] + ' en ' + Math.abs(b.ts - prev.ts) + ' ms (límite ' + lim + ')' } });
    }
  }
  for (const k of fk) if (T.maxJump[k]) RT.lastVal[e.dev + '|' + k] = { v: b.f[k], ts: b.ts };

  // aceptado
  const tags = ingest ? Object.assign({}, b.tags, { via: 'ingest' }) : b.tags;
  good.push({ measurement: b.m, tags, fields: b.f, timestamp: new Date(b.ts) });
  RT.stats.telemetryAccepted++;
