  if (origin && allowed.includes(origin)) { h['Access-Control-Allow-Origin'] = origin; h['Vary'] = 'Origin'; }   // sin origen permitido no se envía la cabecera: el navegador bloquea la respuesta
  return h;
}
// ─────────────────────────────────────────────────────────────────────

// GET /api/health  →  para comprobar rápido que Node-RED y la simulación están vivos.
msg.payload = { status: 'ok', simulation: !!flow.get('state'), time: Date.now() };
msg.statusCode = 200;
msg.headers = apiHeaders(msg.req);
return msg;

// ── Cabeceras de la API: CORS restringido al origen del frontend (generado) ─
function apiHeaders(req) {
  const h = { 'content-type': 'application/json', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' };
  const origin = req && req.headers && req.headers.origin;
  const allowed = String(env.get('CASA_ALLOWED_ORIGINS') || 'http://localhost:5173,http://127.0.0.1:5173,http://localhost:4173,http://127.0.0.1:4173').split(',').map((x) => x.trim()).filter(Boolean);
  if (origin && allowed.includes(origin)) { h['Access-Control-Allow-Origin'] = origin; h['Vary'] = 'Origin'; }   // sin origen permitido no se envía la cabecera: el navegador bloquea la respuesta
  return h;
}
// ─────────────────────────────────────────────────────────────────────

// Si InfluxDB no responde, la API contesta con un error claro en lugar de quedarse colgada.
// El detalle técnico (dirección interna, puerto…) solo se devuelve si CASA_VERBOSE_ERRORS=on (desarrollo local):
// en un servidor público ese texto revelaría la red interna.
const reason = (msg.error && msg.error.message) || 'InfluxDB no disponible';
const verbose = String(env.get('CASA_VERBOSE_ERRORS') || 'on').toLowerCase() !== 'off';
msg.statusCode = 502;
msg.payload = verbose ? { error: 'No se pudo consultar InfluxDB', detail: String(reason).slice(0, 200) } : { error: 'No se pudo consultar InfluxDB' };
msg.headers = apiHeaders(msg.req);
const S = flow.get('state');
let tel = null;
if (S) {
  const a = S.pipe.api, t = Date.now();
  a.errors += 1; a.lastAt = t;
  tel = { payload: { type: 'pipeline', ts: t, api: Object.assign({}, a) } };
}
return [msg, tel];

// Cada 5 s Node-RED LEE de InfluxDB (no de su memoria) cuántas lecturas de consumo hay en los últimos 10 min
// y cuál es la más reciente. Así se demuestra que lo que envía se está guardando de verdad.
const cfg = global.get('cfg');
if (!cfg) return null;
const B = (cfg.INFLUX || {}).bucket || 'casa_iot';
msg._t0 = Date.now();
msg.query = `from(bucket: "${B}")
  |> range(start: -10m)
  |> filter(fn: (r) => r._measurement == "power" and r._field == "watts")
  |> aggregateWindow(every: 1m, fn: count, createEmpty: false)
  |> group()
  |> sum()`;
return msg;

const cfg = global.get('cfg');
if (!cfg) return null;
const B = (cfg.INFLUX || {}).bucket || 'casa_iot';
const rows = Array.isArray(msg.payload) ? msg.payload : [];
msg._points = rows.length ? Number(rows[0]._value) || 0 : 0;
msg.query = `from(bucket: "${B}")
  |> range(start: -10m)
  |> filter(fn: (r) => r._measurement == "power" and r._field == "watts")
  |> group()
  |> max(column: "_time")`;
return msg;

// Publica a la interfaz lo que InfluxDB confirmó: puntos guardados, hora del último y lo que tardó la lectura.
const S = flow.get('state');
if (!S) return null;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const last = rows.length ? Date.parse(rows[0]._time) : NaN;
const now = Date.now();
S.pipe.store = { ok: true, points10m: msg._points || 0, lastPointAt: Number.isFinite(last) ? last : null, readMs: now - msg._t0, checkedAt: now };
node.status({ fill: 'green', shape: 'dot', text: S.pipe.store.points10m + ' puntos · ' + S.pipe.store.readMs + ' ms' });
return { payload: { type: 'pipeline', ts: now, store: S.pipe.store } };

// Si InfluxDB rechaza una escritura o una lectura, la interfaz lo muestra en rojo en el panel «Pipeline IoT».
const S = flow.get('state');
if (!S) return null;
const src = msg.error && msg.error.source ? msg.error.source.id : '';
// El texto del error llega a TODOS los clientes (también a los de solo lectura): en un servidor público puede revelar la red
// interna (direcciones y puertos). Con CASA_VERBOSE_ERRORS=off se muestra un mensaje genérico; el detalle queda en el registro de Node-RED.
const verbose = String(env.get('CASA_VERBOSE_ERRORS') || 'on').toLowerCase() !== 'off';
const text = verbose ? String((msg.error && msg.error.message) || 'Error').slice(0, 160) : 'Error de InfluxDB (el detalle está en el registro de Node-RED)';
const now = Date.now();
if (src.indexOf('casa_influx_batch') === 0) {   // lote principal, huellas de integridad
  S.pipe.errors += 1; S.pipe.lastError = text; S.pipe.lastErrorAt = now;
  return { payload: { type: 'pipeline', ts: now, writes: { batches: S.pipe.batches, points: S.pipe.points, lastBatchAt: S.pipe.lastBatchAt, errors: S.pipe.errors, lastError: text, lastErrorAt: now } } };
}
S.pipe.store = Object.assign({}, S.pipe.store, { ok: false, error: text, checkedAt: now });
return { payload: { type: 'pipeline', ts: now, store: S.pipe.store } };
